import { instantToString, parseInstant } from '@absoluteui/core';
import { DateTimePicker, type DateTimePickerChangeDetail } from '@absoluteui/components/date-time-picker';

const host = document.createElement('div');
document.body.append(host);
DateTimePicker.create(host, {
  label: 'Departure',
  name: 'departure',
  required: true,
  timezone: 'America/New_York',
  min: parseInstant('2026-01-01T05:00:00Z'),
  max: parseInstant('2027-01-01T05:00:00Z'),
});
host.addEventListener('aui-change', (event) => {
  const { value, validity } = (event as CustomEvent<DateTimePickerChangeDetail>).detail;
  host.dataset.value = value && validity.valid ? instantToString(value) : '';
});

import { DateTimePicker } from '@absoluteui/components/date-time-picker';

const host = document.createElement('div');
document.body.append(host);
const picker = DateTimePicker.create(host, { label: 'Maintenance window', timezone: 'Europe/Berlin', disambiguation: 'reject', step: 15, hourCycle: 'h23' });
host.addEventListener('aui-change', () => {
  if (picker.validity.error === 'nonexistent-time' || picker.validity.error === 'ambiguous-time') picker.reportValidity();
});
